def v(s): return tuple(int(x) for x in s.split("."))

advisory = {"component": "openssl", "affected": ("1.1.1", "1.1.1.20")}  # [시작, 끝)
sbom = {
    ("A차종", "IVI"):       {"openssl": "1.1.1.12"},
    ("A차종", "텔레매틱스"): {"openssl": "3.0.8"},
    ("B차종", "IVI"):       {"openssl": "1.1.1.21"},
    ("C차종", "게이트웨이"): {"mbedtls": "2.28.0"},
}
lo, hi = map(v, advisory["affected"])
for (car, ecu), parts in sbom.items():
    ver = parts.get(advisory["component"])
    if ver is None:
        print(f"{car} {ecu}: 해당 부품 없음")
    elif lo <= v(ver) < hi:
        print(f"{car} {ecu}: 영향 있음 ({ver}) → 재현·영향도 분석 대상")
    else:
        print(f"{car} {ecu}: 버전 범위 밖 ({ver})")

# A차종 IVI: 영향 있음 (1.1.1.12) → 재현·영향도 분석 대상
# A차종 텔레매틱스: 버전 범위 밖 (3.0.8)
# B차종 IVI: 버전 범위 밖 (1.1.1.21)
# C차종 게이트웨이: 해당 부품 없음
